ring // the quote\n  rating    Int      @default(5) // 1-5 stars\n  avatar    String? // optional image path like /images/avatar-x.png\n  status    String   @default(\"published\") // draft | published\n  sortOrder Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n}\n\nmodel EmailLog {\n  id             String   @id @default(cuid())\n  type           String // post.published | subscriber.welcome | broadcast | inquiry.created | invoice.sent\n  recipientEmail String\n  subject        String\n  postId         String?\n  subscriberId   String?\n  status         String   @default(\"sent\") // queued | sent | failed\n  error          String?\n  sentAt         DateTime @default(now())\n  // ── Phase-1 audit extensions (sent_emails contract) ──\n  bodyText       String? // plain-text version\n  bodyHtml       String? // branded HTML version\n  attachments    String   @default(\"[]\") // JSON [{filename, size, storageUrl?}]\n  invoiceId      String? // related invoice when type=invoice.sent\n\n  @@index([postId])\n  @@index([subscriberId])\n  @@index([sentAt])\n  @@index([invoiceId])\n}\n\n/**\n * ── Phase-1 Module 2: audit-trail models ────────────────────\n * Directive asked for Mongoose models; this stack is Prisma +\n * SQLite (deployed on Render with a persistent disk — migrating\n * to Mongo would break the deployment kit and every preserved\n * workflow). Equivalent Prisma models deliver the same audit\n * goals without the regression. Mappings:\n * received_emails → ReceivedEmail\n * sent_emails     → EmailLog (extended above — the admin Email\n * log UI already reads it; a duplicate table\n * would drift)\n * invoices        → Invoice\n * events          → EventRecord\n * whatsapp_messages → WhatsAppMessage\n */\nmodel ReceivedEmail {\n  id        String   @id @default(cuid())\n  source    String   @default(\"contact\") // contact | ai_chat | manual\n  name      String?\n  email     String?\n  phone  